    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    out = [[0] * w for _ in range(h)]

    # Tile the shape with 2x2 squares and L triominoes.
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            square = {(r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)}
            pieces.append((square, 1))
            l_shapes = [
                ({(r, c + 1), (r + 1, c), (r + 1, c + 1)}, 2),
                ({(r, c), (r, c + 1), (r + 1, c + 1)}, 3),
                ({(r, c), (r + 1, c), (r + 1, c + 1)}, 4),
                ({(r, c), (r, c + 1), (r + 1, c)}, 2),
            ]
            pieces.extend(l_shapes)

    by_cell = {cell: [] for cell in cells}
    for shape, color in pieces:
        if shape <= cells:
            for cell in shape:
                by_cell[cell].append((shape, color))

    def solve(left):
        if not left:
            return True
        cell = min(left, key=lambda p: sum(shape <= left for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= left:
                for r, c in shape:
                    out[r][c] = color
                if solve(left - shape):
                    return True
                for r, c in shape:
                    out[r][c] = 0
        return False

    solve(cells)
    return out

