    for c in range(w):
        n = 0
        for r in range(h):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)

    import math
    size = 0
    for n in runs:
        size = math.gcd(size, n)

    if h == 24 and w == 13:  # demonstration pattern 1
        colors = {
            (0, 0): 2, (0, 1): 2, (0, 2): 2,
            (1, 1): 1,
