def transform(grid):
    h, w = len(grid), len(grid[0])

    # Complete repeating horizontal bands, with one cycle position per
    # observed full-width band.
    bands = {}
    horizontal = True
    for r, row in enumerate(grid):
        nonzero = [x for x in row if x]
        if nonzero:
            if len(nonzero) != w or len(set(nonzero)) != 1:
                horizontal = False
                break
            bands[r] = nonzero[0]

    if horizontal and bands:
        period = len(bands)
        seq = {r % period: color for r, color in bands.items()}
        return [[seq[r % period]] * w for r in range(h)]

    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c]]

    # Diagonal clues define the colors of the repeating diagonal bands.
    candidates = []
    for key_fn in (lambda r, c: r - c, lambda r, c: r + c):
        lines = {}
        for r, c, color in points:
            lines.setdefault(key_fn(r, c), set()).add(color)
        if lines and all(len(colors) == 1 for colors in lines.values()):
            candidates.append((len(lines), key_fn, lines))

    if candidates:
        _, key_fn, lines = min(candidates, key=lambda item: item[0])
        period = len(lines)
        seq = {k % period: next(iter(colors)) for k, colors in lines.items()}
        return [[seq[key_fn(r, c) % period] for c in range(w)]
                for r in range(h)]

    return [row[:] for row in grid]

