    h, w = len(grid), len(grid[0])
    seen = set()
    stack = []

    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == 0:
                stack.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == 0:
                stack.append((r, c))

    while stack:
        r, c = stack.pop()
        if (r, c) in seen or grid[r][c] != 0:
            continue
        seen.add((r, c))
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w:
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    for r, c in seen:
        out[r][c] = 2
    return out

